		await delay(1500);
		response.end(fixture);
	});

	const result = await ky(server.url, {
		timeout: 2000,
		retry: {
			limit: 1,
			delay: () => 0,
		},
	}).text();

	t.is(result, fixture);
	t.is(requestCount, 2);
});

